OUT=Path('output'); slides=[]
def add(title,sub,body,notes,source,section='研究问题',time='1 分钟',short=False,theme=''):
 slides.append(dict(title=title,sub=sub,body=body,notes=notes.strip(),source=source,section=section,time=time,short=short,theme=theme))
def table(head,rows):
 return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def points(items):return '<ul class="points">'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def eq(x,caption=''):return '<div class="equation">'+x+'</div><p class="caption">'+caption+'</p>'
def duo(a,b):return '<div class="duo"><div>'+a+'</div><div>'+b+'</div></div>'
def fig(n,box,name):
 im=Image.open(f'.work/page{n}.png').crop(box);p=Path('.work',name+'.png');im.save(p)
 return '<img class="figure" alt="'+name+'，原论文图表裁剪" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'">'
