add('监管企业集团','Regulating Conglomerates: Evidence from an Energy Conservation Program in China',
'<p class="cover-question">一家企业节能了，<br>整个行业也节能了吗？</p><p class="authors">Qiaoyi Chen · Zhao Chen · Zhikuo Liu<br>Juan Carlos Suárez Serrato · Daniel Yi Xu</p><p>American Economic Review, 2025, 115(2): 408–447</p>',
'''大家好，今天我要介绍的论文是《监管企业集团：来自中国节能项目的证据》，发表于 2025 年的《美国经济评论》。我想先请大家想象一个很简单的场景：一位老板有好几家工厂，政府要求其中最大的那家控制能耗。过了一段时间，这家大工厂确实少用了煤。我们能不能因此认定，整个社会都节能了？
答案取决于其他工厂发生了什么。如果老板把订单交给自己另外几家工厂，或者竞争对手趁机扩大生产，那么名单上企业的节能，就不等于全行业的净节能。这篇论文把这个问题研究得非常具体。今天我会先讲故事和证据，再介绍模型怎样把企业层面的结果加总成政策评价。没有计量经济学基础，也可以沿着这条线听懂。''',
'文献信息：AEA 官方期刊页，DOI 10.1257/aer.20211455；内容依据本地正文与附录',time='45 秒',short=True,theme='dark')
add('全文的核心逻辑','先记住研究链条，再看每一步的证据',
points(['<b>受监管企业：</b>能耗下降，产出也下降，未发现显著的额外能效改善','<b>集团与市场：</b>关联企业和无关竞争者承接部分生产','<b>政策评价：</b>模型估计净节能约 4%，集团整体监管可改善效果'])+'<p class="takeaway">评价政策，需要把监管名单之外的企业也算进来。</p>',
'''这篇文章可以分成三个层次。第一层，作者看直接受到监管的企业。结果是，它们的能耗下降了，产出也下降了，但是没有出现显著的、相对于对照组的能源效率改善。第二层，作者顺着股权关系找到了这些企业的关联企业，发现一部分生产活动转了过去。此外，没有股权关系的竞争对手也扩大了生产。
第三层，作者把这些反应放进一个行业均衡模型，计算净节能和经济代价。模型估计，全行业净能耗下降约百分之四。如果把整个企业集团作为监管单位，在相同价格上升成本下，节能量还可以增加约百分之十。这里的百分之十是节能量的相对增加，后面会用数字解释。
大家现在不必记所有数字，只要抓住一个问题：当企业能在监管边界之外调整生产时，我们怎样判断监管到底产生了多少实际效果？''', '正文 §II–VI；Table 1–3、Figure 7',short=True)
add('一个集团，两家工厂','教学示例，数值仅用于说明“泄漏”，并非论文估计',
table(['能耗单位','大厂 A：受监管','小厂 B：关联企业','集团合计'],[['政策前','100','40','140'],['政策后','80','52','132'],['变化','−20','+12','−8']])+eq('净节能 8 = 大厂节能 20 − 小厂增耗 12','大厂少用的能源，有一部分在集团内部重新出现'),
'''我们先用一个完全假设的例子理解泄漏。政策前，大厂 A 用一百单位能源，小厂 B 用四十单位，集团一共用一百四十单位。政策以后，大厂 A 只能用八十单位。如果我们只查 A 的账，就会说节约了二十单位。
但是，老板把一部分订单转给 B，B 的能耗从四十增加到五十二。这样集团现在使用一百三十二单位能源，真正净节约的是八单位。原来二十单位的直接节能，被 B 增加的十二单位部分抵消。这种抵消就叫泄漏。
如果市场上其他老板的工厂也增加生产，还要继续扣除它们新增的能耗。请注意，这里没有说所有节能都消失了，也没有说企业一定违法。它们可能完全遵守被监管企业的配额，只是整体效果小于只看名单内企业时的印象。接下来，论文要回答的就是：现实中是否真的发生了这种情况？''','教学示例；概念对应正文 §III',short=True)
add('三个容易混淆的概念','能耗、产出与能效分别回答不同问题',
table(['概念','白话解释','本文口径'],[['能耗 E','用了多少能源','主要观测煤、油、气等一次能源'],['产出 Y','生产活动规模有多大','实证主要使用产值／收入'],['能效 Y/E','一单位能源对应多少产值','产出除以能耗']])+eq('能源强度 = E/Y　　能源效率 = Y/E','两者互为倒数。产值口径也会受到产品价格的影响。'),
'''在讲证据之前，我们要把三个概念分开。能耗是投入了多少能源，产出是生产活动规模有多大，能效是每单位能源对应多少产出。比如原来一百单位能源生产一百单位产品，现在八十单位能源生产八十单位产品，能耗虽然少了，但效率仍然是一比一。只有八十单位能源仍能生产一百单位产品，才体现技术或组织效率的提高。
本文实证中的产出主要是产值或收入，而不是所有产品统一换算后的物理件数。因此，产值除以能耗也可能受价格影响，不能直接当成纯粹的工程技术效率。理论模型会另外区分物理产量和销售收入。
还有一个关键区别：能源强度是每单位产出需要多少能源，能源效率是每单位能源产生多少产出。一个降低，通常对应另一个提高。后面看到这两个术语时，大家不要把方向弄反。''','正文 §I.B、§II，Figure 3 注释',short=True)
add('政策为什么锁定这 1,008 家企业','千家企业节能行动的规模与对象',
'<div class="statrow"><div><strong>1,008</strong><span>实际纳入企业数</span></div><div><strong>47%</strong><span>占 2004 年工业能耗</span></div><div><strong>18 万</strong><span>吨标准煤的入选门槛</span></div></div>'+points(['2006 年公布，按 2004 年历史能耗筛选，覆盖 9 个高耗能行业','政策目标包括提高能效，并到 2011 年节约 1 亿吨标准煤','标准煤是不同能源的统一折算单位，不等于只统计实物煤']),
'''千家企业节能行动虽然叫千家，实际纳入的是一千零八家工业企业。它们来自九个高耗能行业，入选标准是二零零四年的能源消费超过十八万吨标准煤。标准煤是一种共同计量单位，用来把不同能源折算到可比较的尺度，并不是所有企业只使用煤炭。
为什么政府先管它们？因为它们在二零零四年就占了中国工业能耗的百分之四十七，占全国总能耗约三分之一。抓住少数大户，就能覆盖很大的能耗规模，行政上看起来也比较容易。
政策在二零零六年公布，却按照二零零四年的历史能耗选企业。这意味着企业很难在政策公布以后，回头改变自己是否入选。不过，这只减少了操纵名单的担忧，并不意味着大企业和小企业天然可以直接比较。作者仍然需要设计对照组。''','正文 §I.A，原文印刷页 7–8',section='制度与数据',short=True)
add('政策时间线与研究窗口','政策公布时间，与回归使用的政策后时期需要区分',
table(['时间','事件','研究中的用途'],[['2004','决定入选所用的历史能耗','模型主要拟合这一年的企业分布'],['2006','4 月宣布千家企业项目','事件研究的基准年'],['2007–2010/11','考核实施与政策运行','政策后时期，终点依数据而异'],['2012 起','扩展为万家企业项目','此前未受管的后来入选企业可作对照']]),
'''时间线决定了作者怎样比较。二零零四年的能耗决定千家企业名单。二零零六年四月，政策正式公布。二零零七年出台相应监测和考核办法，所以作者把二零零六年作为事件研究的基准年，把二零零六年之后定义为政策后时期。
主分析使用的能耗数据到二零一零年，部分工业企业产出分析到二零一一年。因此，不能笼统地说每一个回归都使用完全相同的年份。二零一二年起，政策扩展到万家企业。这个名字也不是准确的企业数量，实际范围更大。
作者利用这次后续扩围，找出那些后来才受到监管、但在千家企业政策期间尚未受到监管的高耗能企业，作为对照组。这里也留下一个可讨论的问题：既然二零零六年已经宣布政策，企业可能提前反应。因此，基准年是否完全没有政策影响，是我们评价识别时需要保留的限制。''','正文 §I.A、§II；式 (1)–(2)',section='制度与数据')
add('从“提高能效”到“限制能耗”','制度执行方式，决定企业最直接的应对方向',
duo('<h3>原本希望</h3><p>通过节能目标推动技术和效率改善。</p><p>但节能量计算口径复杂，基准与产品结构难以核验。</p>','<h3>实际执行</h3><p>地方依赖可监测的企业能耗配额。</p><p>考核与官员激励相连，企业超额可能面临限电或停产。</p>')+'<p class="takeaway">少开工，也能降低总能耗；能耗配额本身并不保证技术进步。</p>',
'''这页是整篇论文的重要制度基础。政策希望提高能源效率，但提高了多少效率，并不容易核验。企业产品种类不同，历史基准不同，节能量计算方式也复杂。如果政府很难确认某家企业到底靠技术节约了多少能源，就可能转而盯住更容易观察的总能耗。
作者结合政策文件、审计材料和访谈，发现地方实际执行主要依赖能耗配额。配额参考历史能耗、行业预期增长和节能任务，不一定意味着现实能耗必须低于去年，而是限制相对于原本可能增长路径的能耗。
执行力度也很强。地方官员的考核与目标完成情况有关，企业可能面对限电、停产等措施。所以这不是一个简单的“政府没有认真执行”的故事。恰恰相反，约束确实落到了企业身上，但企业面对的是能耗上限，最直接的反应之一就是少生产。''','正文 §I.A；在线附录 A.2–A.3',section='制度与数据',short=True)
add('作者把四类数据拼在一起','既看生产和能源，也看企业之间的股权关系',
table(['数据','提供什么','在研究里解决什么问题'],[['CESD 环境统计','企业产值与一次能源，2001–2010','能耗、产出、能效是否变化'],['ASIF 工业企业调查','产值、行业、所有制等','关联企业与市场竞争者如何反应'],['CARD 工商注册','股东和企业关联关系','谁属于同一个所有权网络'],['ATS 税收调查','补充产值与能源信息','交叉核对与稳健性检验']])+'<p class="caption">能耗基准样本含 427 家千家企业；CESD 不含完整电力消费，不能忽略这一限制。</p>',
'''只看政策名单不能回答生产有没有转移，作者需要把四种数据拼起来。环境统计数据告诉我们企业用了多少一次能源、创造了多少产值。工业企业调查覆盖更多制造业企业，能帮助作者观察那些规模较小、没有进入主要能耗样本的关联企业。工商注册数据提供股东信息，使作者可以沿着所有权网络寻找联系。税收调查则用来补充和核验部分结果。
大家要记住一个数据限制：CESD 对能源的记录主要是煤、油、气，不包含完整的电力消费。为了减少这一问题，作者基准分析排除了特别依赖电力的行业，并做了替代样本检验。经过样本限制，能耗分析中有四百二十七家千家企业，而不是把一千零八家全部完整观察到。
因此，后面的能耗结果很有信息量，但它不等于对所有能源使用进行了毫无遗漏的直接测量。模型向行业层面推算时，也需要额外的结构假设。''','正文 §I.B–C，脚注 9–10；附录 C、E',section='制度与数据')
add('三类企业，三种比较','每一类比较，都对应一个不同的经济问题',
table(['被研究的企业','与谁比较','要识别的变化'],[['A 受监管企业','后来入选万家、且无集团关联的企业','监管名单内企业的相对变化'],['B 未受管的关联企业','同行业、政策前规模相近的无关企业','集团内部的生产转移'],['C 未受管的无关企业','监管强度不同的行业中的企业','市场层面的间接影响']])+'<p class="takeaway">“未直接受监管”并不等于“完全不受政策影响”。</p>',
'''接下来我们会看到三类企业，先把它们的位置弄清楚。A 是直接受到千家企业政策监管的企业，作者把它们和后来才入选万家企业、并且不属于同一集团的企业比较。B 是没有直接受监管、但与 A 有股权关系的企业。作者为 B 找同行业、政策前规模相近的无关企业作为对照。C 则既没有直接被管，也没有与受监管企业的所有权联系，作者观察它们是否在监管更强的行业里增长更多。
这三类比较不是把三个“差分”连起来的三重差分。它们是几套针对不同对象的双重差分或事件研究设计。现有笔记里有容易让人误会的命名，我们课堂汇报时应当说清楚。
还要特别记住：不在监管名单上，只代表没有直接配额，不代表政策对它毫无影响。市场价格变化、竞争者减产，都可能影响它。这一点会在后面解释为什么 DID 结果不能直接加总。''','正文 §II–III；式 (1)–(3)',section='实证识别',short=True)
add('双重差分：先比较变化，再比较差距','教学示例：共同上涨的部分，要从政策效果中扣掉',
table(['产出指数','政策前','政策后','变化'],[['受监管组','100','90','−10'],['对照组','100','110','+10']])+eq('DID = (90 − 100) − (110 − 100) = −20','若没有政策，受监管组也会增长到 110；实际为 90，与该反事实相差 20 个指数点。'),
'''双重差分这个名字听起来复杂，实际就是做两次减法。看这个教学例子，两组企业政策前的产出指数都设为一百。政策后，受监管组变成九十，对照组变成一百一十。第一次减法分别计算各自变化：受监管组减少十，对照组增加十。第二次减法再把这两种变化相减，得到负二十。
为什么不能只说政策造成减少十？因为没有政策时，受监管企业也可能跟着经济增长而增加产出。如果对照组提供了可信的趋势，那么受监管组本来应该到一百一十，实际只有九十，相差二十。
关键假设是：如果没有政策，两组本来会沿着相似的趋势变化，这叫平行趋势。例子里的负二十是指数点，不是原文回归中的精确百分比。原文主要使用对数指标，而且对照组还可能受到政策溢出，所以我们先用例子理解方法，再讨论真实研究中的复杂性。''','教学示例；原文方法为正文式 (2)',section='实证识别',short=True)
add('原文回归式的白话解释','β 衡量受监管组在政策后的额外相对变化',
eq('Yᵢⱼₖₜ = β (Treatᵢ × Postₜ) + αᵢ + ηⱼₜ + δₖₜ + X′ᵢₜγ + εᵢⱼₖₜ')+table(['组成部分','含义'],[['Treat × Post','受监管企业，而且处于 2007 年及以后'],['αᵢ','控制每家企业长期不变的特点'],['ηⱼₜ、δₖₜ','控制行业当年冲击、地区当年冲击'],['Xᵢₜ','部分规格另控制企业特征']]),
'''这一页我们只拆公式，不做推导。左边 Y 是要解释的结果，可以是能耗、产出或能效的对数。右边最重要的是 Treat 乘以 Post：Treat 表示企业是否属于千家企业，Post 表示是否处于二零零六年之后。它前面的系数 beta，就是作者最关心的政策后相对变化。
企业固定效应 alpha，可以理解为给每家企业保留自己的起点，避免把某些企业一直比较大误当成政策效果。行业乘年份固定效应，控制某一年整个行业共同经历的变化。地区乘年份固定效应，则控制某一省在某一年共同遭遇的冲击。有些列还加入所有制、出口、盈利能力和企业年龄等特征。
这些控制能够减少混淆，但不会自动保证因果识别。最重要的条件仍然是：扣除这些因素以后，没有另一个只在政策后、只影响受监管组的因素恰好出现。作者还要看政策前趋势，并做多种稳健性检验。''','正文式 (2)，Table 1；标准误按企业聚类',section='实证识别')
add('事件研究图怎么读','原文 Figure 3 A–B：受监管企业的能耗变化',
F3+points(['左图：每个点是相对于 2006 年的处理组与对照组差异，竖线是 95% 置信区间','右图：政策后两组能耗路径分开，受监管组相对下降','政策前差异没有明显系统性趋势，为平行趋势提供支持']),
'''现在看作者的原图。左边横轴是年份，纵轴是处理组与对照组的相对差异，二零零六年被设为零。蓝色点代表估计值，上下的竖线是百分之九十五置信区间，它表示估计有多不确定。政策之前，点大致围绕零附近，没有明显持续上升或下降的系统性趋势。政策之后，点逐步往负方向走，说明受监管企业的能耗相对于对照组下降了。
右边更直观，是两组的变化路径。作者为了便于比较，对对照组的政策前水平做了缩放。大家看两条线在政策后分开，就能理解左图系数为什么变成负数。
这里要准确表达：政策前趋势比较接近，是支持识别假设的证据，不是数学证明。置信区间较宽也意味着某些差异可能没有被精确检测出来。我们不能仅凭“政策前不显著”就宣布所有因果问题已经解决。''','原文 Figure 3 A–B，正文印刷页 13／本地 PDF 第 14 页',section='实证结果',short=True)
add('受监管企业：能耗与产出同时下降','Table 1 第 (4) 列，加入企业特征控制',
table(['结果变量','对数系数 β','标准误','p 值'],[['能耗','<b class="neg">−0.128</b>','0.048','0.008'],['产出','<b class="neg">−0.145</b>','0.042','0.001'],['能效','−0.019','0.047','0.691']])+'<p class="takeaway">主要反应与缩减生产一致，未发现显著的额外能效提升。</p><p class="caption">沿用原文近似口径可读作 −12.8%、−14.5%。精确百分比换算为 100×(eᵝ−1)。</p>',
'''表一直接回答政策管住了什么。这里统一展示第四列，避免把不同规格随意拼在一起。能耗系数是负零点一二八，产出系数是负零点一四五，两者都在统计上显著。按照原文常用的近似说法，可以分别理解为能耗相对下降约百分之十二点八，产出相对下降约百分之十四点五。
能源效率的系数是负零点零一九，p 值约零点六九，不能拒绝没有额外变化的假设。因此，把能耗下降和产出下降放在一起，比较合理的解释是企业主要通过压缩生产活动来应对约束。
注意两件事。第一，这些是相对于对照组的政策效应，不是简单的同比增长率。第二，对数系数乘一百是近似百分比，精确换算需要用指数函数。例如负零点一二八对应的精确比例约为负百分之十二。为了方便与论文对照，主讲沿用作者的近似口径，备份页会列精确换算。''','Table 1 第 (4) 列；正文 §II',section='实证结果',short=True)
add('“没有显著改善”应该怎样理解','不能把统计结论说成“技术永远不会进步”',
points(['相对于对照组，没有发现政策带来显著的额外能效改善','两组企业的平均能效，在样本期内都出现过提高','Table 1 第 (3) 列的置信区间上限，约排除超过 4% 的相对改善','较长时期的设备更新与技术进步，超出基准短期分析的完整覆盖范围']),
'''“能效没有显著改善”这句话很容易被讲过头。作者并没有说中国这些企业的能效完全没有变化。原图反而显示，两组企业的平均能效都在提高。真正的意思是，受到这项政策监管的企业，并没有比可比的对照企业获得显著更多的改善。
另一个误区是把统计上不显著直接等同于真实效果恰好为零。样本有噪声，估计存在置信区间。不过，作者指出，在同时加入行业和省份年度固定效应的第三列中，百分之九十五置信区间的上端大约只能容纳百分之四的改善。这意味着很大的额外提升与数据不太相符。
最后，短期缺乏效果，不代表更长时期一定没有技术更新。更换工业设备往往需要时间、资金和稳定预期。论文的基准模型为了贴合观察到的短期反应，固定了能效，附录再讨论允许能效投资的扩展。''','正文 §II，Figure 3 E–F；Table 1 第 (3) 列；附录 J.1',section='实证结果')
add('关联企业承接了生产','未受管、同一细分行业的关联企业相对扩张',
table(['结果','Table 2 第 (4) 列','解释'],[['产出','<b class="pos">+0.127</b>','约 +12.7%，p < 0.001'],['能耗','<b class="pos">+0.318</b>','约 +31.8%，p = 0.001'],['能效','−0.087','未显著，p = 0.380']])+'<p class="caption">产出与能耗使用不同覆盖范围的样本，不能直接用 12.7% 减 31.8% 推算能效。</p>',
'''接下来，作者沿着股权关系去找没有直接受到监管的关联企业。如果集团内部确实转移了生产，那么这些企业的产出应该上升。结果与这个预测一致：表二第四列中，关联企业产出系数是正零点一二七，按照原文近似口径约增长百分之十二点七。能耗也显著增加，但能效变化没有统计显著性。
为什么我专门在下面写了样本提醒？因为产出数据覆盖的关联企业更多，而能耗数据主要覆盖其中较大的企业。所以，不能把百分之十二点七和百分之三十一点八直接相减，然后宣称这些企业的能效恶化了某个精确比例。它们不是完全相同企业、完全相同观测集合上的两个均值。
这组结果支持生产向关联企业转移，但作者还需要排除另一种解释：会不会所有大集团的关联企业恰好都在这个时期增长？下一页的安慰剂检验，就是针对这种可能性。''','Table 2，第 (4) 列；正文 §III 对能耗小样本的说明',section='实证结果',short=True)
add('安慰剂检验：关联关系本身够不够','原文 Figure 4 A–B：能替代生产的关联企业才明显扩张',
F4+duo('<h3>左图：同一 4 位码行业</h3><p>产品更相近，较可能承接生产。政策后产出明显增加。</p>','<h3>右图：同大类、不同小类</h3><p>有股权联系，但产品不同。未发现显著的产出变化。</p>'),
'''这张图把两类关联企业分开。左边是与受监管企业属于同一个四位码细分行业的关联企业。可以把它理解为大家生产的产品比较接近，比如同一种工业材料，因而有可能承接彼此的订单。右边仍然与受监管企业有股权关系，也在同一个二位码大行业，但不属于相同的四位码小行业，产品替代性比较弱。
如果我们看到的增长只是“大集团普遍经营得更好”，那么两类关联企业都有可能上升。但图中明显的上升主要出现在左边，右边没有出现同样清晰的反应。这就更符合生产替代的机制。
当然，安慰剂检验不能排除每一种竞争性解释，它提供的是更有针对性的支持。我们也没有直接看到每一笔订单从 A 转移到 B。作者通过政策时点、所有权关系、行业相似性和产出反应共同构建证据链。''','原文 Figure 4 A–B；Table 2 Panel A–B',section='实证结果',short=True)
add('“转移约 40%”是怎么算出来的','必须把关联企业的数量和规模一起算进去',
eq('2.45 × 19.3% × 12.7% ≈ 6.0%','平均每家受管企业对应 2.45 家关联企业；每家关联企业约为受管企业规模的 19.3%')+eq('6.0% ÷ 14.5% ≈ 41%','新增关联企业产出，占受管企业产出损失的比例')+'<p class="takeaway">这是产出损失的承接比例，不是节能量被抵消的比例。</p>',
'''这里有一个非常适合课堂讲清楚的计算。我们不能看到大厂下降百分之十四点五、小厂增长百分之十二点七，就说两者基本抵消，因为它们的规模不同。
作者发现，每家受监管企业平均对应二点四五家同行业关联企业，而一家关联企业的平均规模，只有受监管企业的百分之十九点三。如果把受监管企业原来的产出设为一百，那么这些关联企业合计原来的规模大约是四十七点三。它们再增长百分之十二点七，新增产出就大约等于六。
受监管企业损失了十四点五，关联企业承接了六，所以六除以十四点五，大约是百分之四十一，也就是论文概括的百分之四十。这是依据平均规模和回归结果做的近似换算，不是精确逐笔追踪。最重要的是，它衡量的是产出损失的转移比例，不能拿来直接计算能源泄漏率，也不能套用到每一个集团。''','正文 §III，脚注 13；Table 1–2 第 (4) 列；附录 F',section='实证结果',short=True)
add('没有股权关系的竞争者也会扩张','市场泄漏来自供给收缩后的市场机会',
'<div class="bigclaim">约 <b>7%–8%</b></div><p class="lead">平均监管暴露对应的未受管、无关企业产出增幅</p>'+points(['行业内受监管企业收缩，其他企业可能获得更多市场需求','作者比较监管强度不同的行业，并排除受管企业的关联企业','产出包含价格与数量反应，不能全部解释成物理产量增加']),
'''刚才我们只看了同一个老板内部的调整。但集团内的小厂无法补回全部损失，市场上还会出现空间。可以想象，原来某家大厂供应很多产品，现在它减少供应，其他公司的产品就可能更好卖，价格也可能上升。
作者用行业的节能目标除以政策前行业能耗，构造监管强度。然后观察，在监管更强的行业里，没有受到直接监管、也没有与受监管企业关联的企业，产出是否增加得更多。结果是，按平均监管暴露归一化后，产出增加约百分之七到百分之八。
这个结果提供了第二种泄漏证据。但我们要比前面的企业比较更谨慎，因为识别变化发生在行业层面，也更容易受到行业特定冲击的影响。而且这里的产出主要是收入，它既包含卖出的数量，也包含价格变化。论文的结构模型会把这些反应放在同一个框架里解释。''','正文式 (3)；Table 3 Panel A，Figure 5 Panel A',section='实证结果',short=True)
add('有溢出时，DID 测到的是相对效果','教学示例：对照组可能因为这项政策而获益',
table(['相对于“无政策”的变化','受监管企业','对照企业'],[['假设的政策总影响','−14%','+6%']])+eq('相对效果 ≈ −14% − (+6%) = −20%','DID 中的 −20%，不能直接说成受监管企业相对无政策情形减少了 20%')+'<p class="takeaway">模型的任务之一，是把相对变化与政策总影响分开。</p>',
'''现在我们回到一个重要问题：如果对照组也受到政策影响，DID 还能怎样解释？先看这个便于心算的示例。假设政策让受监管企业相对于没有政策的状态下降百分之十四，同时让对照企业因为竞争减少而增长百分之六。那么两组之间的相对差距就大约是负百分之二十。
DID 可以帮助我们看到这二十个百分点左右的相对变化，但如果把它全部归因于受监管企业自身，就会夸大它的直接下降，因为其中一部分来自对照组上涨。这里的算术是近似示意，原文的严格分解在对数尺度上进行。
这不意味着 DID 没有价值。它仍然告诉我们两组的变化出现了多大分化。真正的问题是，从“相对差异”走到“政策相对于完全没有政策的总影响”，需要知道对照组和价格如何反应。作者因此引入结构模型，而不是直接把各个回归系数相加。''','教学示例；正式模型分解见 Table 5',section='从实证到模型',short=True)
add('为什么需要一个行业均衡模型','微观证据回答“谁变了”，政策评价还要回答“合起来怎样”',
table(['仅靠前面的比较','模型补充的内容'],[['处理组相对对照组的变化','两组相对于无政策情形的变化'],['观察到部分企业的反应','按规模与能源份额加总行业变化'],['现有政策下发生了什么','更换监管单位或使用能源税会怎样'],['能耗与产出是否下降','节能收益能否补偿经济成本']]),
'''前面的经验结果已经很丰富，但还差几块拼图。第一，我们需要知道对照组相对于没有政策时到底增加了多少。第二，不同企业大小不同，不能对增长率简单求平均。第三，企业反应会影响价格，价格变化又会影响其他企业的生产，这些相互影响需要一起求解。
所谓行业均衡模型，就是把消费者需求、企业生产、集团内部调配和市场价格之间的关系写成一套能够同时成立的规则。我们给它一个政策约束，求出所有企业调整以后，市场最终会达到怎样的新状态。
模型的好处，是可以计算我们无法直接观察到的反事实，比如同样的经济代价下，如果监管整个集团会怎样。它的代价，是结论依赖模型假设和参数。因此，后面要同时看模型如何贴合数据，以及哪些假设限制了结论的适用范围。''','正文 §IV–VI',section='结构模型')
add('模型里的企业集团','同一集团能调配生产，但调配并非没有代价',
points(['一个集团生产一种产品，集团内多个企业可以生产这种产品','集团间产品存在差异，消费者可以在不同产品之间替代','集团内企业规模报酬递减，复制管理与技术也不完全','短期内企业数量与资本配置给定，主要调整能源和可变投入']),
'''作者把真实世界中复杂的集团简化成一个可计算的结构。每个集团提供一种有自身特点的产品，这种产品可以由集团里的多个企业生产。基准模型里，同集团企业生产的产品可以完全替代，所以订单确实可以在集团内部重新分配。不同集团的产品则有差异，但消费者仍然可以在它们之间替代。
为什么老板不把所有生产都转到没受管的小厂？模型给了两个原因。第一，单个企业存在规模报酬递减，越往一家工厂追加投入，新增产出越有限。第二，集团不能把技术和管理能力毫无损失地复制到所有关联企业，所以其他企业通常更小。
政策发生以后，机器设备和企业数量在短期内不容易改变，集团主要调整能源和可变投入。这组假设贴近论文关注的短期反应，但也意味着模型没有完整覆盖多年以后新工厂进入、设备更新和行业技术进步。''','正文 §IV.A–B，脚注 15–18；§V.B',section='结构模型',short=True)
add('生产函数的直觉','能源与可变投入需要配合，机器资本短期难以搬走',
eq('qᵢ = φ δⁱ⁻¹ kᵢ<sup>νₖ</sup> [min(lᵢ, ηᵢeᵢ)]<sup>νₗ</sup>')+table(['符号','含义'],[['qᵢ、kᵢ、lᵢ、eᵢ','产量、资本、可变投入、能源'],['φ、δ','集团基础效率、关联企业效率保留比例'],['ηᵢ','能源效率参数，基准模型设为 1'],['νₖ + νₗ < 1','规模报酬递减']]),
'''这个生产函数只需要从左往右读。q 是产量，k 是资本，也就是机器设备等投入。l 是可变投入组合，可以理解为随生产调整的劳动和其他投入。e 是能源。最小值符号 min 表示能源和可变投入必须配合使用，哪一边不够，就由哪一边限制有效投入。例如，工人到齐但炉子没能源，生产线也无法正常运行。
phi 表示集团的基础生产能力，delta 的幂表示这种能力在不同关联企业之间逐步衰减。基准模型把能源效率 eta 设为一，是一种标准化处理。它不意味着现实中所有企业绝对一样节能，而是先构建一个与短期未发现额外能效改善相吻合的基准，再在附录放松假设。
最后，两个投入指数加起来小于一，就是规模报酬递减。投入全部增加一倍，产出增加不到一倍。这个设定让扩大某家小厂的生产有真实成本，也解释了为什么集团内部转移不能无限进行。''','正文 §IV.A；此处将原文技术设定合并写出，ν 对应原文规模参数',section='结构模型')
add('为什么集团里常有“一家大、几家小”','模型用效率衰减解释集团内部的规模分布',
eq('qᵢ / q₁ = δ<sup>(i−1)/(1−ν)</sup>')+eq('当 δ = 0.90，ν = 0.90：q₂/q₁ = 0.9¹⁰ ≈ 35%','数据中第二大企业约为最大企业的 29%；模型抓住了快速递减的形状。')+'<p class="takeaway">δ 是效率参数，不能直接把 90% 当成关联企业的产出规模。</p>',
'''这条公式解释为什么一个集团往往是一家大厂配上几家较小的企业。i 表示按规模排序的企业，q 一是最大企业的产量，q i 是第 i 家的产量。delta 是效率在企业之间保留下来的比例，nu 是规模报酬参数。
估计得到 delta 等于零点九，nu 也等于零点九。于是第二家企业相对第一家的产出比例，不是百分之九十，而是零点九的十次方，大约百分之三十五。数据中的对应比例约为百分之二十九，所以模型没有逐点完全一致，但能反映规模快速下降的形状。
为什么效率只差一点，规模却差很多？直觉上，当最大企业更有效率，而扩大它的规模又没有受到非常强的递减约束时，集团会把更多生产集中到它身上。作者用这些政策前的集团规模特征来识别模型参数，后面再看模型是否能解释政策后的变化。''','Proposition 1，式 (5)；Table 4；正文 §V.A',section='结构模型')
add('能耗配额与影子成本','一单位受约束投入，除了买价，还有“稀缺成本”',
eq('e₁ ≤ ξ e₁*，　ξ = 0.80','最大企业的能源使用受限；星号表示无监管时的最优值。')+duo('<h3>受监管企业</h3><p>边际投入成本可理解为<br><b>w + pₑ + λ</b></p>','<h3>未受管关联企业</h3><p>没有直接配额约束<br><b>w + pₑ</b></p>')+'<p class="caption">λ 是放松配额的边际价值，不是政府实际征收的税。ξ 是模型校准，不是每家企业的实测减幅。</p>',
'''在模型里，政策限制集团中最大企业的能源使用，不能超过无政策时最优能耗的百分之八十。这里的百分之二十收紧，是作者结合政策目标作的模型校准，不等于每家企业现实中都恰好少用百分之二十能源。
有了约束以后，能源对这家企业的价值就不只是市场价格。假设再多给它一单位配额能增加利润，它就愿意为放宽约束付出代价。这个边际价值叫影子成本，用 lambda 表示。可以把它想象成看不见的额外成本，但它并不是政府真的向企业收了一笔税。
关联企业没有这个直接约束，于是集团会把部分可变投入移过去。但这种调整会偏离原来更有效率的配置。论文附录估计，基准政策的影子成本相当于可变投入成本的约百分之八点七。它刻画了约束有多紧，同时也帮助衡量集团内部配置扭曲的代价。''','正文 §IV.D，式 (12)；Table 4；附录 G',section='结构模型')
add('模型如何从数据中得到参数','先拟合政策前，再预测政策后',
table(['参数或设定','数值','依据'],[['产品替代弹性 σ','4','外部文献校准'],['规模报酬 ν、可变投入指数 νₗ','0.90、0.80','外部估计与成本份额'],['集团内效率保留 δ','0.900','政策前集团内规模分布'],['效率分布离散度 σₘ','1.239','政策前企业规模分布'],['存活门槛 φ₁','0.609','政策前小企业比例']])+'<p class="caption">核心技术参数主要匹配 2004 年数据矩；政策覆盖份额与配额强度另行校准。</p>',
'''作者不是把政策后的所有变化都直接塞进模型，让模型照着答案复述。主要技术参数来自政策前的数据，例如二零零四年不同规模企业的比例、各规模组的产出份额，以及集团里第二、第三家企业相对于最大企业的大小。
其中，有些参数由外部文献和成本份额给定，比如产品替代弹性和规模报酬。有些参数由矩估计得到。矩估计可以理解为：挑一些数据中的统计特征，然后寻找一组参数，让模型生成的这些统计特征尽量接近真实数据。
政策部分还需要设定监管门槛和配额强度。门槛用来匹配受监管企业的能源份额，配额强度参考政策目标。因此，更准确的说法是：核心生产结构主要在政策前数据上估计，再用政策后 DID 结果检验预测表现，而不是说整个模型完全没有使用任何政策信息。''','Table 4；正文 §V.A–B',section='结构模型')
add('模型能否预测政策后的企业反应','原文 Figure 6 B：把预测与未直接拟合的实证结果比较',
duo(F6,'<h3>读图方法</h3><p>红色方块：模型预测<br>蓝色菱形：实证估计<br>蓝色横线：95% 置信区间</p><h3>主要判断</h3><p>产出反应匹配较好。</p><p>关联企业能耗反应匹配较差，作者明确承认这一点。</p>'),
'''这张图是模型可信度的重要检验。红色方块是模型预测，蓝色菱形是实证估计，横向的线是置信区间。大家主要看，同一行里红色方块与蓝色结果是否接近。
在受监管企业产出、关联企业产出、市场溢出以及集团内部相对变化这些方面，模型的预测总体比较接近实证结果。由于这些政策后结果没有直接作为核心技术参数的拟合目标，这种匹配比只展示政策前拟合更有说服力。
但模型并非处处准确。关联企业能源使用那一行，模型与实证结果差得较多。作者解释，能耗样本主要覆盖较大的关联企业，可能不能代表所有关联企业，但这个解释并没有让误差自动消失。因此，汇报时可以说模型得到多项样本外证据支持，同时保留了能耗匹配不足的限制，不能说模型已经被证明完全正确。''','Figure 6 Panel B；正文 §V.B',section='结构模型',short=True)
add('模型怎样重新解释 DID 系数','Table 5：所有数字为对数变化，乘 100 展示',
table(['对象','相对无政策的总影响','扣除对照组后'],[['受监管企业','−14.0','−14.0 − 6.5 = <b>−20.5</b>'],['关联企业','+19.3','+19.3 − 6.5 = <b>+12.8</b>'],['对照企业','+6.5','也受到市场溢出影响']])+'<p class="takeaway">受管企业的相对降幅更大，关联企业的相对增幅更小。</p><p class="caption">模型分解结果，不是重新估计出的另一张回归表。</p>',
'''前面的教学例子，现在可以对应到原文正式结果。表五中，模型估计受监管企业相对于无政策情形的收入变化是负零点一四，也就是负十四个对数百分点。对照企业因为政策的市场影响，上升六点五个对数百分点。两者一减，模型中的 DID 就是负二十点五，与经验结果接近。
对于关联企业，方向刚好相反。它们相对于无政策情形增长十九点三个对数百分点，但对照企业也增长六点五，因此相对增幅只有十二点八。也就是说，忽略对照组的反应，会夸大受监管企业自身的下降幅度，却低估关联企业相对于无政策状态的增长幅度。
这页全部是模型分解，不要把它当成新的回归系数。它的价值在于说明：同一个微观估计结果，需要结合经济机制才能知道它对应什么政策问题。完整的集团内分配、集团收入和市场需求分解放在备用页。''','Table 5 Panel A–B；式 (17)',section='结构模型',short=True)
add('全行业净节能为什么约为 4%','先算各类集团的反应，再按政策前能源份额加权',
table(['集团类别','政策前能源份额','模型中的能耗变化'],[['含受监管企业的集团','86%','−5.8%'],['其他集团','14%','+6.5%']])+eq('0.86 × (−5.8%) + 0.14 × 6.5% ≈ −4.1%','舍入与对数口径不同，原文报告净节能约 4%，约每年 4,800 万吨标准煤。')+'<p class="caption">86% 是集团及关联企业的份额；56% 是受管企业在高耗能行业的份额；47% 是其在全国工业的份额。</p>',
'''现在终于可以从企业走到全行业。含有受监管企业的集团，内部虽然有生产转移，但合起来的能耗仍下降约百分之五点八。其他集团没有直接受到配额约束，反而因为市场机会增加而提高能耗，模型估计约增长百分之六点五。
接下来按政策前能源份额加权。受监管集团及其关联企业占相关行业模型中能源的百分之八十六，其他集团占百分之十四。所以，零点八六乘负百分之五点八，再加零点一四乘百分之六点五，得到大约负百分之四。因为展示数字有舍入，而且原文有对数口径，心算结果与报告数字不会完全一样。
这里的百分之四是模型测算的行业净效果，不是一个直接回归得到的系数，也不是说全中国所有能源使用都下降了百分之四。作者将它换算为约每年四千八百万吨标准煤。它显著小于只看受管企业相对降幅得到的约一亿吨粗略数字。''','正文 §VI.A，式 (15)，脚注 24；Table 4',section='政策评价',short=True)
add('节能收益与经济成本怎样比较','模型给出一个福利权衡，而不是单看节能吨数',
'<div class="statrow"><div><strong>约 4%</strong><span>行业净能耗下降</span></div><div><strong>约 3.5%</strong><span>行业价格指数上升</span></div></div>'+eq('福利变化 = 消费购买力损失 + 减排与健康收益')+points(['价格提高：同样的支出，能买到的消费组合减少','能源减少：碳排放与相关本地污染损害下降','净福利取决于社会如何评价环境收益']),
'''节能并不是唯一的评价标准。如果为了节约一点能源，付出了非常大的生产和消费代价，政策未必划算。但反过来，哪怕生产受到影响，只要避免的环境和健康损害足够大，政策仍可能提高社会福利。
在论文模型中，政策使行业价格指数上升约百分之三点五。直觉上，同样的钱买到的商品组合减少，消费者购买力下降。另一方面，行业净能耗下降约百分之四，相关碳排放和本地污染也随之减少。
所以，作者比较的是这两种方向相反的变化，而不是仅仅判断煤用得少了没有。这里的百分之三点五是模型中的行业价格指数变化，不能把它说成全国 GDP 下降百分之三点五，也不能说成中国整体物价上涨了这么多。作者使用的福利框架对消费和环境分别赋予权重，下一页会把这个权重换算成更容易理解的美元金额。''','正文式 (11)、(16)；§VI.A，Figure 7',section='政策评价',short=True)
add('161 美元：政策划算所需的收益门槛','每减少 1 吨 CO₂，需要多大的社会收益才能补偿成本？',
'<div class="bigclaim"><b>$161</b><span> / 吨 CO₂</span></div>'+points(['GWTP：政府对减排的总支付意愿，包含气候收益与本地健康收益','以文中本地健康收益 $4–17 计算，所需 SCC 约为 $144–157','不同模型扩展下，门槛约为 $114–199'])+'<p class="caption">这是论文模型与历史数据校准下的福利门槛，不是观测到的碳价、现行税率或政府真实支付。</p>',
'''作者问的是一个有条件的问题：每减少一吨二氧化碳，社会获得的收益至少要有多大，这项政策才值得？在基准模型和历史数据校准下，答案约是一百六十一美元。
这个指标叫政府支付意愿，简称 GWTP。它既包含减少全球气候损害的收益，也包含少烧能源、减少相关本地污染所带来的健康收益。因此，它不能直接等同于碳的社会成本 SCC。按照作者整理的中国本地健康收益估值，每吨二氧化碳对应大约四到十七美元健康收益。把它从一百六十一美元里扣掉，剩下需要由气候收益解释的部分，约为一百四十四到一百五十七美元。
这不是政府真的每吨支付了一百六十一美元，也不是今天市场上的碳价。它是让模型中的收益与成本打平的门槛。作者在不同参数和模型扩展下得到约一百一十四到一百九十九美元，说明具体数值有明显的模型敏感性。原文有时简称“每吨碳”，附录的排放数据明确采用二氧化碳口径，这里统一写吨 CO₂。''','正文 §VI.A；在线附录 I 明确 CO₂ 口径；附录 J',section='政策评价',short=True)
add('把整个集团作为监管单位','相同价格上升成本下，模型给出更多节能',
duo(F7,'<h3>集团整体监管</h3><p class="emph">3.97% 变为 4.36%</p><p>净节能幅度增加约 0.39 个百分点，相当于节能量多约 10%。</p><h3>福利门槛</h3><p>现有政策：$161<br>集团监管：$154<br>统一能源税：$153</p>')+'<p class="caption">关键机制：集团可在总约束内选择更有效率的内部配置。以上为模型反事实。</p>',
'''接下来是最重要的政策反事实。既然集团能在内部转移生产，能不能直接限制整个集团的能耗，而不只限制最大的那一家？这种做法的好处，是集团在满足总体节能任务的同时，可以把生产放在更合适的企业，不必为了绕开单家企业的约束，强行改变内部配置。
图中比较的是相同价格上升成本下的节能效果。现有政策的节能幅度约百分之三点九七，集团整体监管可以达到百分之四点三六。两者相差零点三九个百分点。零点三九除以三点九七，约等于百分之十。所以，论文说节能量多百分之十，并不是说净节能率从百分之四一下跳到百分之十四。
模型中，集团监管的福利门槛下降到约一百五十四美元，接近统一能源税的一百五十三美元。这说明识别并利用集团关系可能有很大价值。但这是依赖模型假设的反事实，实施时还需要识别集团边界、核验能耗，并承担行政成本。''','Figure 7 Panel B；正文 §VI.B，脚注 29–30',section='政策评价',short=True)
add('扩大名单，与改进监管单位的区别','覆盖更多企业，未必能消除集团内部配置扭曲',
table(['政策方案','模型中的主要结论'],[['扩张监管名单','节能增加，但成本与节能的基本权衡变化不大'],['收紧已有企业配额','节能增加，约束成本也增加'],['监管整个集团','减少集团内部配置扭曲，给定价格成本下节能更多'],['统一能源税','模型中的比较基准，福利权衡略优']])+'<p class="caption">税收比较未完整计入税收返还的潜在收益，也不代表现实执行成本完全相同。</p>',
'''作者还比较了几个看起来更直接的办法。第一，扩充监管名单，让更多企业受到配额约束。第二，不扩名单，而是把现有企业的配额进一步收紧。这两种办法都会增加节能，但也增加经济代价，模型里并没有从根本上改变成本和节能之间的权衡。
集团整体监管的不同之处，在于它直接针对前面发现的内部配置问题。集团可以在总任务下保留更有效率的生产分工，所以同样的价格成本对应更多节能。这也是为什么论文标题强调集团，而不仅是讨论监管强度。
统一能源税是另一种比较基准。在这个模型里，它略优于集团监管，但两者已经比较接近。我们不能据此推出任何现实税制都与集团配额差不多，因为模型没有完整处理税收返还可能带来的收益，也没有把复杂行政成本都量化。合适的结论是：在论文设定的短期生产环境中，集团信息有助于改进监管设计。''','正文 §VI.B；Figure 7；脚注 30',section='政策评价')
add('这篇论文的贡献与边界','肯定证据链，同时保留影响结论的限制',
duo('<h3>贡献</h3>'+points(['把监管名单外的集团与市场反应纳入评价','结合制度、微观识别和均衡模型','让政策建议直接对应发现的机制']),'<h3>边界</h3>'+points(['能耗记录不完整覆盖电力','所有权网络基于事后数据，可能有测量误差','短期模型与福利参数限制外推','集团边界和执行成本仍需现实核验'])),
'''我认为这篇论文最突出的贡献，是把企业集团这一组织结构放进了环境政策评价。它没有停留在名单上的企业是否节能，而是继续找生产去了哪里，再用模型计算净效果。制度分析、微观证据和反事实建议之间有明确对应关系。
同时，有几处限制会影响我们对结论的信心。能耗数据没有完整电力信息，作者做了多种检验，但不能把这个缺口说成完全解决。集团网络利用较晚的工商登记信息构建，虽然作者发现重大所有权变化不多，并检验了不同网络口径，仍可能有历史边界测量问题。模型主要考虑短期调整，不能完整代表长期创新、进入退出和设备更新。福利门槛也依赖环境损害估值与模型参数。
最后，把集团作为监管单位在逻辑上合理，但政府能否准确划定复杂集团、监测各家企业，仍有执行难题。这些限制不会推翻所有微观发现，却提醒我们：经验结果、模型推算和政策建议的确定程度并不相同。''','正文脚注 9–10、23、30；附录 C、E、J、K；实施成本讨论为汇报者评价',section='评价与总结',short=True)
add('监管边界需要回应企业的决策边界','汇报结束时，留下这三点',
'<ol class="closing"><li>企业少用能源，可能来自少生产。</li><li>被压缩的生产，可能在集团和市场中重新出现。</li><li>评价和设计政策，需要把这些调整一起算进去。</li></ol><p class="takeaway">讨论：如果你是监管者，会优先扩大名单，还是先识别集团关系？</p>',
'''最后，我用三句话总结今天的汇报。第一，企业的能耗下降，可能主要来自生产减少，所以要同时观察产出和能效。第二，生产减少以后，部分活动会转移到关联企业，也会转移到没有股权关系的市场竞争者，因此受监管企业的节能不等于全行业净节能。第三，政策设计需要考虑企业实际上怎样作决策，集团层面的监管可能比只盯住单家企业更有效。
具体到本文，微观数据支持受监管企业收缩和关联企业扩张，结构模型进一步估计净节能约百分之四，并显示在相同价格成本下，集团监管能让节能量增加约百分之十。这些数量结果要与其短期模型和数据限制一起理解。
我的汇报到这里。留给大家一个讨论问题：如果监管资源有限，我们应该先把更多企业纳入名单，还是先识别已有大企业背后的集团关系？这篇论文提供了一套分析这个选择的方法。谢谢大家。''','基于全文综合；主要定量结论见 §VI',section='评价与总结',short=True,theme='dark')
add('备用 A：为什么没有直接使用断点回归','历史能耗门槛减少名单操纵，但不自动构成可信的断点设计',
points(['原文核心设计是 DID 与事件研究，不是三重差分，也不是 RDD','名单按 2004 年能耗形成，有助于减少政策公布后的操纵','可信 RDD 还需要门槛附近的样本、分配规则和连续性条件','作者报告了缩小到更接近门槛企业的稳健性分析']),
'''如果老师问，既然有十八万吨标准煤的门槛，为什么不直接做断点回归，可以这样回答：门槛提供了一个可能的研究方向，但门槛存在本身不等于一套有效的断点设计。我们还需要在门槛两侧有足够的、口径一致的企业数据，并验证处理分配和其他特征在附近的行为。
这篇论文实际采用的是双重差分和事件研究，用后来才受到监管的企业作为主要对照。历史能耗决定名单，主要帮助缓解政策宣布后操纵入选状态的担忧。作者也在附录里把样本限制到更接近监管门槛的企业，检验结果是否稳健。
因此，准确的介绍应该尊重论文实际使用的方法。我们可以讨论 RDD 作为替代策略需要哪些条件，但不能因为看到一个门槛，就声称作者已经实施了断点回归。也不能把多套 DID 误称为三重差分。''','正文 §II；附录 D.1',section='答辩备用',time='按需')
add('备用 B：对数系数与百分比','精确换算为 100 × (exp(β) − 1)',
table(['结果：第 (4) 列','β','原文近似说法','精确换算'],[['受管企业能耗','−0.128','−12.8%','−12.0%'],['受管企业产出','−0.145','−14.5%','−13.5%'],['关联企业产出','+0.127','+12.7%','+13.5%'],['关联企业能耗','+0.318','+31.8%','+37.4%']])+'<p class="caption">换算不改变方向与统计显著性。系数较大时，近似百分比和精确比例的差异更明显。</p>',
'''如果老师追问系数为什么能读成百分比，可以补充这页。因为左边是结果变量的自然对数，所以 beta 对应的是对数变化。严格地从对数还原成比例，需要先求 e 的 beta 次方，再减一，最后乘一百。
例如能耗的系数负零点一二八，对应精确降幅约百分之十二，而不是精确百分之十二点八。关联企业能耗的零点三一八比较大，精确换算约为百分之三十七点四，与近似说法百分之三十一点八有更明显差距。
主讲沿用原文用系数乘一百的近似表达，是为了便于逐表核对，但应明确它是近似。特别是在做精细的规模计算或比较政策时，不能随意在对数百分点和实际百分比之间来回切换。本文百分之四十的承接比例，也应介绍为作者按其系数和平均规模口径做的近似核算。''','Table 1–2；本页精确比例按指数公式计算',section='答辩备用',time='按需')
add('备用 C：所有权网络怎样定义','关联企业的认定依赖可观察的股权联系',
points(['关联关系包括子公司、被投资企业、股东，以及股东持有的其他企业','每层持股要求至少 25%，最多追溯两层投资关系','排除仅通过国资管理机构形成的共同联系','主分析关注同一 4 位码行业，其他相近行业用于安慰剂']),
'''如果有人问，所有国有企业是不是都被算成一个集团，答案是否定的。作者明确排除了仅仅通过国资管理机构连接起来的关系，否则网络边界会被夸得过大。
作者识别的联系包括受监管企业的子公司、它持有股份的企业、它的股东，以及这些股东持有的其他企业。每一层需要至少百分之二十五的股权联系，最多考虑两层。主分析又进一步限制到同一四位码行业，因为产品足够相似，才比较可能发生生产替代。
这个定义比只看企业名字更有依据，但也不是对所有实际控制权的完美观测。复杂交叉持股、间接控制和历史变更都可能产生测量问题。网络数据较晚，作者用所有权变化记录和替代网络口径做了检验。讨论时可以肯定这套构建方法的透明度，同时承认“经济上的集团”与“数据中识别的集团”仍可能存在差距。''','正文 §I.C，脚注 10；附录 C、F',section='答辩备用',time='按需')
add('备用 D：三种收入效应的正式分解','集团内分配、集团整体规模与市场需求分别起作用',
eq('ln Revenueᵢⱼ = ln(qᵢⱼ / Qⱼ) + ρ ln Qⱼ + ln(R¹⁻ᵖ Pᵖ)'.replace('R¹⁻ᵖ Pᵖ','R<sup>1−ρ</sup> P<sup>ρ</sup>'))+table(['Table 5：对数变化 × 100','分配效应','集团规模项','市场项','合计'],[['受管企业','−12.9','−3.7','+2.6','−14.0'],['关联企业','+20.5','−3.7','+2.6','+19.3'],['对照企业','0','+3.9','+2.6','+6.5']])+'<p class="caption">Qⱼ 为集团物理总产量，R 为行业支出，P 为价格指数，ρ = 0.75；显示值存在舍入误差。</p>',
'''这条式子把一家企业的销售收入分成三部分。第一，它在集团总产量中占多大份额。第二，整个集团的物理产量怎样变化，并经过需求弹性转化成收入。第三，市场整体的需求与价格条件怎样变化。这里 Q 是集团的物理产量，不应把它直接叫作集团收入。
受监管企业的内部份额下降，关联企业的内部份额上升，所以第一项方向相反。但它们属于同一个集团，第二项的集团规模变化相同。它们面对同一个市场，第三项的市场需求变化也相同。
因此，如果直接比较同一个集团里的受监管企业与关联企业，集团规模项和市场项可以抵消，更集中地识别内部配置变化。原文相应的集团内 DID 约为负三十一点五到负三十六点七个对数百分点，模型预测约负三十三点三。展示数值有舍入，直接相减可能出现零点一的差异，不影响经济解释。''','式 (17)、Table 5；集团内 DID 见 Table 3 Panel B',section='答辩备用',time='按需')
add('备用 E：161 美元的换算步骤','福利权重阈值，结合历史收入与排放数据换算',
eq('κ̄/(1−κ̄) ≈ 3.5/4 = 0.875　　故 κ̄ ≈ 0.467')+eq('GWTP = κ̄ × GDP × 0.8 / CO₂')+eq('≈ 0.467 × 2.752 万亿美元 × 0.8 ÷ 63.8 亿吨 ≈ $161/吨','使用论文 2006 年数据及其 0.8 校准因子；精细计算依赖未舍入的模型结果。'),
'''如果需要讲出一百六十一美元的来历，可以用三步说明。第一，模型中的价格成本约为百分之三点五，能源减少约为百分之四，两者的比值约零点八七五。按照论文福利函数，使两者恰好抵消，需要环境权重 kappa 与一减 kappa 的比值达到这个数。
第二，解出 kappa 约为零点四六七。第三，作者用历史宏观数据把这个无量纲权重换成美元每吨。具体采用二零零六年的 GDP 两点七五二万亿美元，以及六十三点八亿吨二氧化碳排放，再加入论文与百分之二十节能目标相联系的零点八校准因子，得到约一百六十一美元。
这里要强调，零点八是作者框架中的校准，不是普遍的经济学常数。因此，这个门槛既依赖行业模型的数量结果，也依赖福利函数和历史换算口径。不能拿到另外一个年份、另外一个行业，还直接照搬同样数字。''','正文式 (16)、§VI.A；在线附录 I',section='答辩备用',time='按需')
add('备用 F：用数字理解泄漏','交互教学示例，帮助理解净效果，不能复现论文模型',
'<div class="lab"><label>受管大厂节能 <b id="directV">20</b> 单位<input id="direct" type="range" min="0" max="40" value="20"></label><label>关联企业增耗 <b id="affiliateV">8</b> 单位<input id="affiliate" type="range" min="0" max="30" value="8"></label><label>市场竞争者增耗 <b id="marketV">4</b> 单位<input id="market" type="range" min="0" max="30" value="4"></label><div class="lab-result">净节能 <strong id="net">8</strong> 单位</div></div><p class="caption">恒等式：净节能 = 受管大厂节能 − 关联企业增耗 − 无关竞争者增耗。负值表示净增耗。</p>',
'''这个交互页只用来说明一个加总关系，不是论文的结构模型。先把受监管大厂的节能设为二十，关联企业新增能耗设为八，市场竞争者新增能耗设为四。那么行业净节能就是二十减八减四，等于八。
现在，如果关联企业承接得更多，它的新增能耗变成十五，其他条件保持不变，净节能就只剩一。继续增加市场竞争者能耗，还可能使净节能变成负数，意味着全行业能耗反而增加。这个结果在教学例子里由我们人为输入，不能据此宣称论文发现了净增耗。论文基准模型报告的仍然是净节能约百分之四。
这个页面帮助我们看到，直接效果再大，也需要同时检查抵消它的变化。真实世界中，这些变量不能随便独立设定，因为价格、技术和生产约束会相互影响。正是为了让它们共同一致，作者才需要一个行业均衡模型。''','教学恒等式；非作者仿真结果',section='答辩备用',time='按需')
add('备用 G：老师可能追问什么','回答先限定口径，再给证据',
table(['问题','简洁回答'],[['政策是不是失败了？','确实减少能源，是否提高福利取决于环境收益估值。'],['是否证明企业造假？','没有。生产转移可以发生在遵守企业配额的情况下。'],['是不是没有任何技术进步？','没有发现相对于对照组的显著额外改善，且主要是短期结果。'],['是否识别了每笔订单转移？','没有，机制证据来自网络、行业相似性和政策前后变化。'],['集团监管一定比碳税好吗？','模型中统一能源税略优，现实实施约束还需另外评估。']]),
'''如果老师问政策是不是失败，可以回答：政策带来了净节能，但也有生产和价格代价，福利判断取决于减排和健康收益估值，所以不能只用成功或失败两个词概括。
如果问是不是证明企业造假，应该回答：论文核心机制是实际生产活动在不同企业之间重新配置，不是直接证明能源数据造假，转移甚至可以在完全遵守单家企业配额的情况下发生。
如果问是不是没有技术进步，应该强调相对于对照组、统计上未显著、以及短期窗口这三个限定。如果问作者是不是直接追踪了订单，就说明证据来自企业网络与产出反应，而非逐笔订单。如果问集团配额是否优于所有碳税方案，可以指出模型中的统一能源税仍略优，论文主要强调利用集团信息能改善不完整监管，而不是证明税收方案没有优势。
这些回答的共同原则是：先说研究具体识别了什么，再说它没有覆盖什么，避免用比证据更强的语言。''','基于正文 §II–VI 与模型限制整理',section='答辩备用',time='按需')
add('备用 H：文献、页码与阅读路线','数字与图表均可回到原文核对',
'<p class="reference">Chen, Qiaoyi, Zhao Chen, Zhikuo Liu, Juan Carlos Suárez Serrato, and Daniel Yi Xu. 2025. “Regulating Conglomerates: Evidence from an Energy Conservation Program in China.” <i>American Economic Review</i>, 115(2): 408–447.</p><p><a href="https://www.aeaweb.org/articles?id=10.1257/aer.20211455" target="_blank" rel="noopener">AEA 官方论文页面与 DOI</a></p>'+table(['阅读目标','本地正文的印刷页'],[['制度、数据与实证结果','7–21 页，Tables 1–3'],['模型与参数估计','22–35 页，Tables 4–5'],['福利与政策反事实','36–41 页，Figure 7'],['数据与敏感性补充','独立在线附录 C、E、F、I、J']])+'<p class="caption">本地稿本印刷页比 PDF 页码少 1，与正式期刊页码不同。独立附录：22048.pdf。</p>',
'''最后这页方便大家回到原文。正式发表信息已经按美国经济学会的期刊页面核对，是二零二五年《美国经济评论》第一百一十五卷第二期，页码四百零八到四百四十七。
我们手里的本地 PDF 是包含附录的稿本，页眉仍然保留稿本格式，因此文中的印刷页码与正式期刊页码不同。演示文稿主要按照本地稿本的表号、图号和章节给出处，不能直接拿本地第十四页当作正式期刊第十四页。独立的在线附录文件共有一百三十六页，也包含在综合 PDF 后半部分。
如果只复习汇报主线，可以先看表一到表三，然后看图六的模型验证、表五的 DID 分解，最后看图七的政策比较。需要回应数据缺口时，看附录 C 和 E。需要回应福利门槛的口径和敏感性时，看附录 I 和 J。这条路线能帮助我们把每一个关键说法落回具体证据。''','AEA 官方期刊页；本地 Chen_et_al_conglomerates.pdf、22048.pdf',section='答辩备用',time='按需')
